// SunRiseSet.cpp - Calculate sun rise and set times for a given date
// Compares both CAARiseTransitSet (old/deprecated) and CAARiseTransitSet2 (new) APIs
// Usage: ./SunRiseSet yyyy-mm-dd [longitude] [latitude] [--center]
// Times are output in UT (Universal Time)
//
// NOTE: Input uses standard GPS convention (negative west, positive east)
//       The program internally converts to AA+ convention (positive west)
//
// Options:
//   --center    Ignore the Sun's semi-diameter (center crosses horizon)
//   --no-refrac Ignore atmospheric refraction (geometric horizon)
//   --average   Use USNO standard h0=-0.8333 deg (ignores --center and --no-refrac)
//   Both --center and --no-refrac: Sun's center crosses geometric horizon (h0=0)
//   Default:    Upper limb at refracted horizon (calculated from actual distance and STP refraction)
//
// The Sun's semi-diameter is calculated from its actual distance using CAADiameters::SunSemidiameterA()
// Refraction at horizon is calculated using CAARefraction::RefractionFromTrue() at STP (1013.25 mbar, 0°C)

#include "stdafx.h"
#include "AA+.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>

// Default location: Cambridge area (for testing)
// Using standard GPS convention (negative west)
static constexpr double DEFAULT_LONGITUDE = -1.0 * (71.0 + 6.0/60.0 + 36.0/3600.0);  // Degrees (standard GPS: negative west)
static constexpr double DEFAULT_LATITUDE = 42.0 + 22.0/60.0 + 12.0/3600.0;    // Degrees

// Get Sun's Right Ascension and Declination for a given Julian Day (UTC)
static void GetSolarRaDec(double JD_UTC, double& RA, double& Dec)
{
    const double JD_TT = CAADynamicalTime::UTC2TT(JD_UTC);
    const double lambda = CAASun::ApparentEclipticLongitude(JD_TT, false);
    const double beta = CAASun::ApparentEclipticLatitude(JD_TT, false);
    const double epsilon = CAANutation::TrueObliquityOfEcliptic(JD_TT);
    CAA2DCoordinate coord = CAACoordinateTransformation::Ecliptic2Equatorial(lambda, beta, epsilon);
    RA = coord.X;
    Dec = coord.Y;
}

// Parse date string in yyyy-mm-dd format
static bool ParseDate(const char* dateStr, long& year, long& month, long& day)
{
    if (std::strlen(dateStr) != 10)
        return false;
    if (dateStr[4] != '-' || dateStr[7] != '-')
        return false;
    
    char yearStr[5] = {0};
    char monthStr[3] = {0};
    char dayStr[3] = {0};
    
    std::strncpy(yearStr, dateStr, 4);
    std::strncpy(monthStr, dateStr + 5, 2);
    std::strncpy(dayStr, dateStr + 8, 2);
    
    year = std::atol(yearStr);
    month = std::atol(monthStr);
    day = std::atol(dayStr);
    
    // Basic validation
    if (month < 1 || month > 12)
        return false;
    if (day < 1 || day > 31)
        return false;
    
    return true;
}

int main(int argc, char* argv[])
{
    // Parse command line arguments
    if (argc < 2)
    {
        std::printf("Usage: %s yyyy-mm-dd [longitude] [latitude] [options]\n", argv[0]);
        std::printf("  longitude: degrees (standard GPS: negative west, positive east)\n");
        std::printf("  latitude: degrees (negative = south, positive = north)\n");
        std::printf("  --center:    ignore Sun's semi-diameter (use center, not upper limb)\n");
        std::printf("  --no-refrac: ignore atmospheric refraction (geometric horizon)\n");
        std::printf("  --average:   use USNO standard h0=-0.8333 deg (average values)\n");
        std::printf("  Default location: Boston area (-71.05, 42.35)\n");
        std::printf("\nExample: %s 2025-12-10 -71.05 42.35                     # upper limb, refracted\n", argv[0]);
        std::printf("         %s 2025-12-10 -71.05 42.35 --center             # center, refracted\n", argv[0]);
        std::printf("         %s 2025-12-10 -71.05 42.35 --no-refrac          # upper limb, geometric\n", argv[0]);
        std::printf("         %s 2025-12-10 -71.05 42.35 --center --no-refrac # center, geometric\n", argv[0]);
        std::printf("         %s 2025-12-10 -71.05 42.35 --average            # USNO standard\n", argv[0]);
        return 1;
    }
    
    long year = 0;
    long month = 0;
    long day = 0;
    
    if (!ParseDate(argv[1], year, month, day))
    {
        std::printf("Error: Invalid date format. Use yyyy-mm-dd\n");
        return 1;
    }
    
    double longitude = DEFAULT_LONGITUDE;
    double latitude = DEFAULT_LATITUDE;
    bool useCenter = false;
    bool noRefraction = false;
    bool useAverage = false;
    
    // Parse remaining arguments (can be in any order after date)
    for (int i = 2; i < argc; i++)
    {
        if (std::strcmp(argv[i], "--center") == 0)
        {
            useCenter = true;
        }
        else if (std::strcmp(argv[i], "--no-refrac") == 0)
        {
            noRefraction = true;
        }
        else if (std::strcmp(argv[i], "--average") == 0)
        {
            useAverage = true;
        }
        else if (i == 2 && argv[i][0] != '-' || (i == 2 && std::isdigit(argv[i][1])))
        {
            longitude = std::atof(argv[i]);
        }
        else if (i == 3 && std::strcmp(argv[i], "--center") != 0)
        {
            latitude = std::atof(argv[i]);
        }
    }
    
    // Convert from GPS convention (negative west) to AA+ convention (positive west)
    const double aaLongitude = -longitude;
    
    // Calculate Julian Day for the start and end of the specified day (UTC)
    const double JD = CAADate::DateToJD(year, month, static_cast<double>(day), true);
    const double startJD = JD;
    const double endJD = JD + 1.0;
    
    // Print header
    std::printf("\n");
    std::printf("Sun Rise/Set Times for %04ld-%02ld-%02ld\n", year, month, day);
    std::printf("Location: Longitude %.4f deg, Latitude %.4f deg\n", longitude, latitude);
    std::printf("================================================================\n\n");
    
    // =========================================================================
    // METHOD 1: New CAARiseTransitSet2 class (recommended)
    // =========================================================================
    std::printf("=== CAARiseTransitSet2 (New/Recommended) ===\n\n");
    
    // Convert UTC JD to TT (Terrestrial Time) for the calculation
    const double startTT = CAADynamicalTime::UTC2TT(startJD);
    const double endTT = CAADynamicalTime::UTC2TT(endJD);
    
    // Calculate rise/transit/set events for the Sun
    // h0 components:
    //   Refraction at horizon: calculated from CAARefraction::RefractionFromTrue at STP (1013.25 mbar, 0°C)
    //   Sun's semi-diameter: calculated from CAADiameters::SunSemidiameterA based on Earth-Sun distance
    
    // Get the Sun's distance (in AU) at the middle of the day for semi-diameter calculation
    const double midDayTT = (startTT + endTT) / 2.0;
    const double sunDistance = CAAEarth::RadiusVector(midDayTT, false);  // Distance in AU
    
    // Calculate Sun's semi-diameter in degrees (SunSemidiameterA returns arcseconds)
    const double sunSemiDiameterArcsec = CAADiameters::SunSemidiameterA(sunDistance);
    const double sunSemiDiameterDeg = sunSemiDiameterArcsec / 3600.0;
    
    // Calculate atmospheric refraction at horizon (altitude=0) at STP
    // STP: Pressure = 1013.25 mbar, Temperature = 0°C
    const double refractionAtHorizonDeg = CAARefraction::RefractionFromTrue(0.0, 1013.25, 0.0);
    
    // Build h0 based on options
    double h0 = 0.0;
    if (useAverage)
    {
        // USNO standard value: -0.8333 degrees
        // This is an average value combining ~34 arcmin refraction + ~16 arcmin semi-diameter
        h0 = -0.8333;
    }
    else
    {
        if (!useCenter)
            h0 -= sunSemiDiameterDeg;    // Account for Sun's size (upper limb)
        if (!noRefraction)
            h0 -= refractionAtHorizonDeg; // Account for atmospheric refraction
    }
    
    // Print mode and calculated values
    const char* modeDesc;
    if (useAverage)
        modeDesc = "USNO standard (h0=-0.8333 deg)";
    else if (useCenter && noRefraction)
        modeDesc = "Sun center at geometric horizon";
    else if (useCenter)
        modeDesc = "Sun center at refracted horizon";
    else if (noRefraction)
        modeDesc = "Upper limb at geometric horizon";
    else
        modeDesc = "Upper limb at refracted horizon";
    std::printf("Mode: %s\n", modeDesc);
    std::printf("  Sun semi-diameter: %.4f deg (%.2f arcsec), Distance: %.6f AU\n", 
        sunSemiDiameterDeg, sunSemiDiameterArcsec, sunDistance);
    std::printf("  Refraction at horizon (STP): %.4f deg\n", refractionAtHorizonDeg);
    std::printf("  h0 = %.4f deg\n", h0);
    std::printf("Times are in UT (Universal Time)\n\n");
    
    std::vector<CAARiseTransitSetDetails2> events = CAARiseTransitSet2::Calculate(
        startTT, endTT, CAARiseTransitSet2::Object::SUN, aaLongitude, latitude, h0, 0.0001, true);
    
    for (const auto& event : events)
    {
        // Convert TT back to UTC
        const double eventJD_UTC = CAADynamicalTime::TT2UTC(event.JD);
        
        // Get the date/time components
        CAADate dateTime(eventJD_UTC, true);
        long eventYear = 0;
        long eventMonth = 0;
        long eventDay = 0;
        long eventHour = 0;
        long eventMinute = 0;
        double eventSecond = 0;
        dateTime.Get(eventYear, eventMonth, eventDay, eventHour, eventMinute, eventSecond);
        
        switch (event.type)
        {
            case CAARiseTransitSetDetails2::Type::Rise:
            {
                std::printf("  Sunrise:  %02ld:%02ld:%02.0f UT  (Bearing: %.2f°)\n", 
                    eventHour, eventMinute, eventSecond, event.Bearing);
                break;
            }
            case CAARiseTransitSetDetails2::Type::Set:
            {
                std::printf("  Sunset:   %02ld:%02ld:%02.0f UT  (Bearing: %.2f°)\n", 
                    eventHour, eventMinute, eventSecond, event.Bearing);
                break;
            }
            case CAARiseTransitSetDetails2::Type::SouthernTransit:
            {
                std::printf("  Transit:  %02ld:%02ld:%02.0f UT  (Altitude: %.2f°)\n", 
                    eventHour, eventMinute, eventSecond, event.GeometricAltitude);
                break;
            }
            default:
                break;
        }
    }
    
    std::printf("\n");
    
    // =========================================================================
    // METHOD 2: Old CAARiseTransitSet class (deprecated)
    // This requires calculating the Sun's RA/Dec for 3 consecutive days
    // =========================================================================
    std::printf("=== CAARiseTransitSet (Old/Deprecated) ===\n\n");
    
    // Get Sun's RA and Dec for three consecutive days (day before, day of, day after)
    double Alpha1 = 0, Delta1 = 0;  // Day before
    double Alpha2 = 0, Delta2 = 0;  // Day of interest  
    double Alpha3 = 0, Delta3 = 0;  // Day after
    
    GetSolarRaDec(JD - 1.0, Alpha1, Delta1);
    GetSolarRaDec(JD, Alpha2, Delta2);
    GetSolarRaDec(JD + 1.0, Alpha3, Delta3);
    
    // Call the old API
    CAARiseTransitSetDetails details = CAARiseTransitSet::Calculate(
        JD, Alpha1, Delta1, Alpha2, Delta2, Alpha3, Delta3, 
        aaLongitude, latitude, h0);
    
    // Convert fractional day times to hours:minutes:seconds
    if (details.bRiseValid)
    {
        int riseHour = static_cast<int>(details.Rise);
        double riseMinFrac = (details.Rise - riseHour) * 60.0;
        int riseMin = static_cast<int>(riseMinFrac);
        int riseSec = static_cast<int>((riseMinFrac - riseMin) * 60.0 + 0.5);
        if (riseSec >= 60) { riseSec -= 60; riseMin++; }
        if (riseMin >= 60) { riseMin -= 60; riseHour++; }
        std::printf("  Sunrise:  %02d:%02d:%02d UT\n", riseHour, riseMin, riseSec);
    }
    else
    {
        std::printf("  Sunrise:  N/A (does not rise)\n");
    }
    
    if (details.bTransitValid)
    {
        int transitHour = static_cast<int>(details.Transit);
        double transitMinFrac = (details.Transit - transitHour) * 60.0;
        int transitMin = static_cast<int>(transitMinFrac);
        int transitSec = static_cast<int>((transitMinFrac - transitMin) * 60.0 + 0.5);
        if (transitSec >= 60) { transitSec -= 60; transitMin++; }
        if (transitMin >= 60) { transitMin -= 60; transitHour++; }
        std::printf("  Transit:  %02d:%02d:%02d UT  (Above horizon: %s)\n", 
            transitHour, transitMin, transitSec,
            details.bTransitAboveHorizon ? "Yes" : "No");
    }
    else
    {
        std::printf("  Transit:  N/A\n");
    }
    
    if (details.bSetValid)
    {
        int setHour = static_cast<int>(details.Set);
        double setMinFrac = (details.Set - setHour) * 60.0;
        int setMin = static_cast<int>(setMinFrac);
        int setSec = static_cast<int>((setMinFrac - setMin) * 60.0 + 0.5);
        if (setSec >= 60) { setSec -= 60; setMin++; }
        if (setMin >= 60) { setMin -= 60; setHour++; }
        std::printf("  Sunset:   %02d:%02d:%02d UT\n", setHour, setMin, setSec);
    }
    else
    {
        std::printf("  Sunset:   N/A (does not set)\n");
    }
    
    std::printf("\n");
    
    // =========================================================================
    // Show comparison summary
    // =========================================================================
    std::printf("=== Comparison Notes ===\n");
    std::printf("The new CAARiseTransitSet2 class is recommended because:\n");
    std::printf("  - It handles edge cases better (polar regions, etc.)\n");
    std::printf("  - It provides bearing/azimuth for rise/set events\n");
    std::printf("  - It provides geometric altitude for transit\n");
    std::printf("  - It handles twilight events (civil, nautical, astronomical)\n");
    std::printf("  - It doesn't require manual RA/Dec interpolation\n");
    std::printf("\n");
    
    return 0;
}
